package app.streamnest;
import org.junit.Test;import static org.junit.Assert.*;import java.util.*;import org.json.*;
public class AnimePlaybackTest {
 @Test public void stallIgnoresPauseAndSeek(){PlaybackStall s=new PlaybackStall();assertFalse(s.sample(1000,5000,60000,true));assertTrue(s.sample(47000,5000,60000,true));assertFalse(s.sample(48000,5000,60000,true));assertFalse(s.sample(49000,10000,60000,true));assertFalse(s.sample(99000,10000,60000,false));assertFalse(s.sample(100000,10000,60000,true));}

 @Test public void packFolderDoesNotOverrideMember()throws Exception{List<String> paths=Arrays.asList("Black Clover S01E158-S01E170/Black Clover S01E158.mkv","Black Clover S01E158-S01E170/Black Clover S01E159.mkv");assertEquals(1,EpisodeFiles.select(paths,Arrays.asList(100L,100L),-1,"",true,1,159,159));assertTrue(MediaTracks.language("eng","Full dialogue","en"));assertTrue(MediaTracks.language("und","English","en"));assertTrue(MediaTracks.partial("English Signs & Songs"));assertFalse(MediaTracks.language("jpn","Japanese","en"));}
 @Test public void knownRunDoesNotGuessFutureSeasons()throws Exception{JSONArray rows=new JSONArray().put(new JSONObject().put("season",1).put("number",170)).put(new JSONObject().put("season",2).put("number",1));CanonicalEpisodes.knownAnime(rows,"tt7441658");assertEquals(170,rows.getJSONObject(0).getInt("absolute"));assertFalse(rows.getJSONObject(1).has("absolute"));assertEquals(1,NyaaEpisodeSources.match("[Fansub] Black Clover S01E159 [1080p]","Black Clover",1,159,159));}
 @Test public void subtitlesRequireExactHashAndUniqueFile()throws Exception{String hash=String.join("",Collections.nCopies(40,"a"));JSONObject attachment=new JSONObject().put("type",1).put("id",124).put("info",new JSONObject().put("codec","ASS").put("lang","en").put("name","Full English"));JSONObject doc=new JSONObject().put("btih",hash).put("files",new JSONArray().put(new JSONObject().put("filename","Pack/01.mkv").put("attachments",new JSONArray().put(attachment))).put(new JSONObject().put("filename","Pack/02.mkv")));assertEquals(1,AnimeSubtitles.candidates(doc,hash,"01.mkv","en").size());assertTrue(AnimeSubtitles.candidates(doc,hash,"","en").isEmpty());assertTrue(AnimeSubtitles.candidates(doc,hash,"02.mkv","en").isEmpty());}
}
